insert into public.chapters (chapter, title, scenarios) values (8, 'Human Resource Management: Building Your Dream Team', '{"The New Hire": "Francesca begins her career working in the human resources department of a major corporation. She is asked to help ensure the organization is following the federal guidelines for employment."}'::jsonb) on conflict (chapter) do update set title = excluded.title, scenarios = excluded.scenarios;
insert into public.questions (id, chapter, num, scenario, question, options, answer, marked, note, unsure) values
('c8-q01', 8, 1, null, 'The first three activities of the human resource management (HRM) process are about ________.', '["recruiting", "planning", "training", "downsizing"]'::jsonb, 'B', 'B', null, false),
('c8-q02', 8, 2, null, 'Of the choices given, the most accurate description of the human resource management is that it is concerned with ________ competent employees.', '["obtaining", "obtaining, training, motivating, and retaining", "obtaining, training, and motivating", "training and keeping"]'::jsonb, 'B', 'B', null, false),
('c8-q03', 8, 3, null, 'For the most part, ________ are involved in HR decisions within their own department or unit.', '["very few managers", "some managers", "most managers", "all managers"]'::jsonb, 'D', 'D', null, false),
('c8-q04', 8, 4, null, 'Employment planning involves ________.', '["addition of staff only", "addition of staff and reduction of staff only", "addition of staff, reduction of staff, and selection only", "addition of staff, reduction of staff, motivation of staff, and selection"]'::jsonb, 'C', 'C', null, false),
('c8-q05', 8, 5, null, 'Which one of the following is the goal of employment planning?', '["selecting competent employees", "obtaining competent employees with up-to-date skills", "obtaining competent and high-performing employees", "selecting high-performing employees only"]'::jsonb, 'A', 'A', null, false),
('c8-q06', 8, 6, null, 'The last steps of the HRM process deal with ________.', '["performance and compensation", "training and compensation", "compensation only", "skills"]'::jsonb, 'A', 'A', null, false),
('c8-q07', 8, 7, null, 'The most important environmental factor in the HRM process is ________.', '["the business environment", "the natural environment", "the legal environment", "the scientific community"]'::jsonb, 'C', 'C', null, false),
('c8-q08', 8, 8, null, '________ prohibits discrimination based on race, color, religion, national origin, or sex.', '["The Privacy Act", "Title VII of the Civil Rights Act", "The Equal Pay Act", "The Sarbanes-Oxley Act"]'::jsonb, 'B', 'B', null, false),
('c8-q09', 8, 9, null, 'A wheelchair-bound applicant may be denied a job ________.', '["under no circumstances", "if the job is strenuous or physically tiring in some way", "if the job requires complete physical mobility", "in some states"]'::jsonb, 'C', 'C', 'On the sheet B is also marked, C is circled. Under the Americans with Disabilities Act an applicant can only be rejected if the disability prevents performing essential job functions – e.g. a job requiring complete physical mobility.', false),
('c8-q10', 8, 10, null, 'Affirmative action programs seek to make sure that employers ________ minority groups.', '["pay equal wages to", "enhance employment opportunities for", "provide unemployment benefits for", "establish training programs for"]'::jsonb, 'B', 'B', null, false),
('c8-q11', 8, 11, null, 'Which U.S. law gives you the legal right to see your professor''s letter of recommendation?', '["Civil Rights Act of 1991", "Privacy Act of 1974", "Polygraph Protection Act of 1988", "Sarbanes-Oxley Act of 2002"]'::jsonb, 'B', 'B', 'On the sheet D is also circled. The Privacy Act of 1974 gives employees (and students) the right to examine letters of reference about them.', false),
('c8-q12', 8, 12, 'The New Hire', 'In setting up interviews for an executive position, Francesca makes sure to include candidates of different ethnic backgrounds, including individuals from protected minority groups. Which kind of program is she attempting to carry out?', '["minority protection", "positive action", "diversity protection", "affirmative action"]'::jsonb, 'D', 'D', 'On the sheet B is also marked, D is circled. Programs that enhance employment opportunities for protected groups = affirmative action.', false),
('c8-q13', 8, 13, 'The New Hire', 'Prior to setting up the interviews for the executive position, Francesca spent a great deal of time analyzing the position and determining what skills, attitudes, and actions it would require. This lengthy review is called a ________.', '["job description", "job specification", "job title", "job analysis"]'::jsonb, 'D', 'D', 'On the sheet B is also marked, D is circled. The lengthy assessment of a job and the behaviors needed to perform it = job analysis.', false),
('c8-q14', 8, 14, null, 'The first step in any employment planning process involves making a ________.', '["job description", "human resource inventory", "product evaluation", "job specification"]'::jsonb, 'B', 'B', null, false),
('c8-q15', 8, 15, null, 'The lengthy process by which a job is examined in detail in order to identify the skills, knowledge and behaviors necessary to perform the job is known as a ________.', '["job description", "job specification", "job definition", "job analysis"]'::jsonb, 'D', 'D', null, false),
('c8-q16', 8, 16, null, 'As one of his first tasks in a new job, Steve''s boss asks him to develop a database that lists the educational level, special capabilities, and specialized skills of all the employees in his firm. This is known as a ________.', '["job description", "human resource inventory", "lengthy process", "job analysis"]'::jsonb, 'B', 'B', null, false),
('c8-q17', 8, 17, null, 'A job description is ________.', '["not a written document", "a written document used to describe a job to job candidates", "something that employers keep secret from job candidates", "the official title for the job"]'::jsonb, 'B', 'B', null, false),
('c8-q18', 8, 18, null, 'A job specification is ________.', '["a list of job qualifications", "a detailed description of the job", "the description of a job that is used by an employment agency", "usually several pages in length"]'::jsonb, 'A', 'A', null, false),
('c8-q19', 8, 19, null, 'HR managers can accurately estimate human resource needs for an organization by evaluating which one of the following?', '["employment and unemployment statistics", "the general state of the economy", "demand for the organization''s product", "how competitors are performing"]'::jsonb, 'C', 'C', null, false),
('c8-q20', 8, 20, null, 'A written statement of what a job holder does in his or her job, how it is done, and why it is done is known as a ________.', '["job specification", "job qualification", "job definition", "job description"]'::jsonb, 'D', 'D', null, false),
('c8-q21', 8, 21, null, 'Downsizing seems to harm ________.', '["victims who are dismissed only", "both victims who are dismissed and survivors who stayed on", "survivors who stayed on only", "managers who carried out the dismissals and their families only"]'::jsonb, 'B', 'B', null, false),
('c8-q22', 8, 22, null, 'To improve workplace diversity, a manager might ________.', '["advertise in ethnic newspapers", "tighten his recruiting net", "solicit referrals from existing employees", "post a notice that states he is an equal opportunity employer"]'::jsonb, 'A', 'A', null, false),
('c8-q23', 8, 23, null, 'According to the EEOC, sexual harassment is ________ that creates a hostile environment, interferes with a person''s work or diminishes the person''s employment opportunities.', '["any speech", "any unwanted or unsolicited speech or physical conduct", "any speech of a sexual nature", "any speech or physical conduct of a sexual nature"]'::jsonb, 'B', 'B', 'B is circled, D is also slightly marked on the sheet. The textbook definition stresses that the conduct is UNWANTED/unsolicited; please double-check with your instructor.', true),
('c8-q24', 8, 24, null, '________ are filed with the EEOC each year.', '["More sexual harassment complaints from males than females", "More sexual harassment complaints from females than males", "About an equal number of sexual harassment complaints from males and females", "Almost no sexual harassment complaints from males"]'::jsonb, 'B', 'B', null, false),
('c8-q25', 8, 25, null, 'If an employee rebuffs inappropriate sexual advances from her boss but still receives a promotion, ________.', '["the boss can''t be guilty of sexual harassment", "the employee is not allowed to lodge a complaint", "the boss can still be guilty of sexual harassment", "the employee is not allowed to lodge a complaint if she accepts the promotion"]'::jsonb, 'C', 'C', null, false),
('c8-q26', 8, 26, null, 'The key to most sexual harassment cases against an organization is whether the organization ________.', '["knew about the behavior and what it did to stop it", "told other employees in the department that harassment occurred", "fired the employee after the charges were lodged", "had hired a known sex offender"]'::jsonb, 'A', 'A', null, false),
('c8-q27', 8, 27, null, 'What financial threat does sexual harassment pose to companies?', '["minor risk of fine", "small legal fees only", "enormous risk of major lawsuit settlements", "none, because companies are insured against harassment"]'::jsonb, 'C', 'C', null, false),
('c8-q28', 8, 28, null, 'Who would usually hear an appeal if an employee felt he or she had been inappropriately accused of sexual harassment?', '["the employee''s direct supervisor", "the director of human resources", "a manager at a higher level not associated with the case", "a manager at a higher level who is already involved in the case"]'::jsonb, 'C', 'C', 'On the sheet B is also marked, C is circled. Appeals should be heard by a higher-level manager who is not associated with the case.', false),
('c8-q29', 8, 29, null, 'Which one of the following would be considered grounds for a sexual harassment charge?', '["jokes that had a sexual theme but no one found offensive", "artwork that, while some considered classic, made some employees feel uncomfortable", "hiring a male employee who had been previously convicted of a sex crime", "consensual dating between an employee and supervisor"]'::jsonb, 'B', 'B', null, false),
('c8-q30', 8, 30, null, 'Part-time, temporary, and contract workers who are available for hire on an as-needed basis are known as ________.', '["consultants", "core employees", "summer employees", "a contingent workforce"]'::jsonb, 'D', 'D', null, false),
('c8-q31', 8, 31, null, 'Which one of the following is commonly considered a category of workforce diversity?', '["education level", "computer skills", "style of dress", "age"]'::jsonb, 'D', 'D', null, false),
('c8-q32', 8, 32, null, 'Which one of the following would be most likely to be true of two random people of the same race?', '["They are likely to have very different skin color and hair type.", "They are unlikely to speak the same language.", "They are likely to have similar skin color and hair type.", "They are likely to share the same cultural traditions."]'::jsonb, 'C', 'C', null, false),
('c8-q33', 8, 33, null, 'In addition to prohibiting age discrimination, what else does the Age Discrimination Act do?', '["Sets the mandatory age for receiving Social Security benefits.", "Allows for early retirement for age related causes of poor performance.", "Restricts mandatory retirement at specific ages.", "Created the Equal Employment Opportunity Commission."]'::jsonb, 'C', 'C', null, false),
('c8-q34', 8, 34, null, 'Which kind of discrimination is NOT prohibited under federal law?', '["discrimination against gays and lesbians", "discrimination against Muslims", "discrimination against people from the Middle East", "discrimination against women or men"]'::jsonb, 'A', 'A', null, false),
('c8-q35', 8, 35, null, 'Which problems are women LEAST likely to face in today''s workplace?', '["a gender pay gap", "being outnumbered in the workplace", "career interruptions due to childbirth", "skepticism about whether they are qualified to do the job"]'::jsonb, 'B', 'B', null, false),
('c8-q36', 8, 36, null, 'Which one of the following countries'' laws pertaining to HRM practices is most closely parallel to those in the United States?', '["Canada", "Mexico", "Australia", "Germany"]'::jsonb, 'A', 'A', null, false),
('c8-q37', 8, 37, null, '________ in Germany give(s) employees the right to participate in personnel decisions.', '["Collective bargaining", "Unionization", "Board representatives", "Work councils"]'::jsonb, 'D', 'D', 'On the sheet C is also marked, D is circled. German work councils (Betriebsräte) give employees co-determination rights in personnel decisions; board representatives sit on the supervisory board.', false),
('c8-q38', 8, 38, null, 'In global companies, a major cause of the line between work and non-work getting blurred is ________.', '["employees needing to commute long distances", "needing to communicate with overseas operations in different time zones", "needing to communicate on a face-to-face basis with employees", "employees needing to work on holidays"]'::jsonb, 'B', 'B', null, false),
('c8-q39', 8, 39, null, 'To find out more about a job with a title of "assistant media buyer," you would find this to be most helpful.', '["job title", "job specification", "job listing", "job description"]'::jsonb, 'D', 'D', null, false),
('c8-q40', 8, 40, null, 'Which one of the following is the goal of employment planning?', '["selecting competent employees", "obtaining competent employees with up-to-date skills", "obtaining competent and high-performing employees", "selecting high-performing employees only"]'::jsonb, 'A', 'A', 'Same question as Q5. On the sheet A and C are both circled here; A is consistent with Q5 (employment planning ensures competent employees are identified and selected).', false)
insert into public.open_questions (id, chapter, num, question, model_answer) values
('c8-o1', 8, 1, 'In a short essay, discuss why sexual harassment is such a difficult problem in today''s workplace.', 'Sexual harassment is any unwanted action or activity of a sexual nature that explicitly or implicitly affects a person''s employment, performance or work environment. It is such a difficult problem because:
